        "Χωριζόμενο πρόθημα: ich schleiche mich ein, schlich mich ein, habe mich eingeschlichen. Ο τόπος όπου μπαίνει κανείς κρυφά δηλώνεται με in + αιτιατική (in das Haus, ins Haus). Στον παρακείμενο χρησιμοποιείται το hat, επειδή το ρήμα είναι αυτοπαθές."
