        "Τύποι: empört sich, empörte sich, hat sich empört. Για ποιο πράγμα αγανακτεί κανείς δηλώνεται με über + αιτιατική: sich über die Lüge empören. Η αντίσταση σε κάποιον εκφράζεται με gegen + αιτιατική.",
