        "Τύποι: wechselt, wechselte, hat gewechselt. Ως μεταβατικό ρήμα θέλει αιτιατική: etwas wechseln. Για αλλαγή κατεύθυνσης χρησιμοποιούνται οι προθέσεις in/auf/zu: Er wechselt zu einem anderen Verein.",
        "Το ουσιαστικό είναι der Wechsel (αλλαγή). Όταν κάνουμε κάτι διαφορετικό (και δεν το αντικαθιστούμε), χρησιμοποιείται συχνότερα το ändern ή το sich verändern."
